<script setup lang="ts">
import {ref,computed,onMounted,onBeforeUnmount} from 'vue';
import * as T from 'three';
import {OrbitControls} from 'three/addons/controls/OrbitControls.js';
import {articles,type KnowledgeSource} from './knowledge';
type Node={id:string;kind:string;label:string;pattern:string;code?:string;image?:string;thumbnail?:string;usable?:boolean;creatable?:boolean;article_id?:string;summary?:string;source_refs?:KnowledgeSource[];origin?:string};
type Edge={source:string;target:string;kind:string;status?:string;evidence?:string;weight?:number};
const emit=defineEmits(['pattern','choose','read','pattern-create','focus-pattern']);
const host=ref<HTMLDivElement>(),hoverLabel=ref<HTMLDivElement>(),data=ref<{nodes:Node[];edges:Edge[]}|null>(null),focus=ref<Node|null>(null),hovered=ref<Node|null>(null),query=ref(''),kind=ref('pattern'),failed=ref(false),loading=ref(true),rotating=ref(!matchMedia('(prefers-reduced-motion: reduce)').matches),dragMode=ref(false),dragging=ref(false),layoutChanged=ref(false),readingIndex=ref(Math.floor(Math.random()*articles.length));
const hits=computed(()=>{const q=query.value.trim().toLowerCase();return (data.value?.nodes||[]).filter(n=>(q||kind.value==='all'||n.kind===kind.value)&&(!q||(n.label+' '+n.id+' '+n.pattern).toLowerCase().includes(q))).slice(0,q?40:60)});
const relations=computed(()=>data.value?.edges.filter(e=>e.kind==='mapping'&&(e.source===focus.value?.id||e.target===focus.value?.id))||[]);
const relatedArticles=computed(()=>focus.value?articles.filter(a=>a.id===focus.value!.article_id||a.pattern===focus.value!.pattern).sort((a,b)=>Number(b.id===focus.value!.article_id)-Number(a.id===focus.value!.article_id)):[]);
const contextRelations=computed(()=>data.value?.edges.filter(e=>['reading','derivation'].includes(e.kind)&&(e.source===focus.value?.id||e.target===focus.value?.id))||[]);
const contemporary=computed(()=>focus.value?.origin==='contemporary'||selectedPattern.value?.origin==='contemporary');
function relatedNode(e:Edge){return data.value?.nodes.find(n=>n.id===(e.source===focus.value?.id?e.target:e.source))}
function followRelation(e:Edge){const n=relatedNode(e);if(n)select(n)}
function referenceUrl(url:string){return /^https?:\/\//.test(url)?url:'#'}
const readingPool=computed(()=>[...relatedArticles.value,...articles.filter(a=>!relatedArticles.value.includes(a))]);
const recommendation=computed(()=>readingPool.value[readingIndex.value%readingPool.value.length]!);
const selectedPattern=computed(()=>data.value?.nodes.find(n=>n.kind==='pattern'&&n.pattern===focus.value?.pattern));
let renderer:T.WebGLRenderer|undefined,scene:T.Scene|undefined,camera:T.PerspectiveCamera|undefined,controls:OrbitControls|undefined,frame=0,observer:ResizeObserver|undefined,instances:T.InstancedMesh|undefined,highlight:T.LineSegments|undefined,selectionHalo:T.Sprite|undefined,hoverHalo:T.Sprite|undefined;
const points=new Map<string,T.Object3D>(),indices=new Map<string,number>(),cards=new Map<string,T.Mesh>(),baseColors=new Map<string,T.Color>(),edgeLayers:{edges:Edge[];lines:T.LineSegments}[]=[],changedPositions:Record<string,number[]>={};
const ray=new T.Raycaster(),pointer=new T.Vector2(),plane=new T.Plane(),planeHit=new T.Vector3(),dragOffset=new T.Vector3(),scratch=new T.Vector3(),direction=new T.Vector3();
let start={x:0,y:0},dragNode:Node|null=null,dragPointer=-1,alive=true,previousTime=0,lastHover='',lastInteraction=0;
const abortController=new AbortController();
const colors:Record<string,number>={pattern:0xe6bc77,'图元':0xd6e2df,'构图':0x9fcbb9,'语义':0xc6a4d8,'工艺适配':0xe1a98e,'文化意象':0xe7ca8b,'感性意象':0xa7d0b2,'场景意象':0x97b9d1,'地域意象':0xb0bdcf,'知识文章':0x9fc8f2};
function shuffleReading(){const length=readingPool.value.length;readingIndex.value=(readingIndex.value+1+Math.floor(Math.random()*Math.max(1,length-1)))%length}
function syncMotion(){if(controls)controls.autoRotate=rotating.value&&!dragMode.value&&!dragging.value}
function toggleRotation(){rotating.value=!rotating.value;syncMotion()}
function toggleDrag(){dragMode.value=!dragMode.value;if(controls)controls.enableRotate=!dragMode.value;syncMotion()}
function zoom(factor:number){if(!controls||!camera)return;camera.position.sub(controls.target).multiplyScalar(factor).add(controls.target);controls.update();lastInteraction=performance.now()}
function resetView(){if(!controls||!camera)return;controls.target.set(0,0,0);camera.position.set(0,7,33);controls.update();lastInteraction=performance.now()}
function locate(){const p=focus.value&&points.get(focus.value.id);if(!p||!camera||!controls)return;controls.target.copy(p.position);camera.position.copy(p.position).add(new T.Vector3(0,2.5,9));controls.update();rotating.value=false;syncMotion()}
function recolor(){if(!instances||!data.value)return;const selected=focus.value?.id,neighbors=new Set<string>();if(selected){neighbors.add(selected);for(const e of data.value.edges)if(e.source===selected||e.target===selected){neighbors.add(e.source);neighbors.add(e.target)}}for(const n of data.value.nodes){const color=baseColors.get(n.id)!.clone();if(selected&&!neighbors.has(n.id))color.multiplyScalar(.44);if(n.id===selected)color.set(0xffe7a8);if(n.id===hovered.value?.id)color.set(0xffffff);instances.setColorAt(indices.get(n.id)!,color)}if(instances.instanceColor)instances.instanceColor.needsUpdate=true;for(const [id,card] of cards)(card.material as T.MeshBasicMaterial).opacity=selected?(neighbors.has(id)?.98:.32):.88}
function coordinates(edges:Edge[]){const values:number[]=[];for(const e of edges){const a=points.get(e.source),b=points.get(e.target);if(a&&b)values.push(...a.position.toArray(),...b.position.toArray())}return values}
function updateConnections(){for(const layer of edgeLayers){const attribute=layer.lines.geometry.getAttribute('position') as T.BufferAttribute;attribute.array.set(coordinates(layer.edges));attribute.needsUpdate=true;layer.lines.geometry.computeBoundingSphere()}if(highlight&&focus.value){const edges=data.value!.edges.filter(e=>e.source===focus.value!.id||e.target===focus.value!.id);highlight.geometry.dispose();highlight.geometry=new T.BufferGeometry();highlight.geometry.setAttribute('position',new T.Float32BufferAttribute(coordinates(edges),3))}}
function updateHighlight(){if(!scene)return;if(highlight){scene.remove(highlight);highlight.geometry.dispose();(highlight.material as T.Material).dispose();highlight=undefined}if(focus.value){const edges=data.value!.edges.filter(e=>e.source===focus.value!.id||e.target===focus.value!.id),geometry=new T.BufferGeometry();geometry.setAttribute('position',new T.Float32BufferAttribute(coordinates(edges),3));highlight=new T.LineSegments(geometry,new T.LineBasicMaterial({color:0xf9dc9c,transparent:true,opacity:.92,depthWrite:false}));scene.add(highlight)}if(selectionHalo){selectionHalo.visible=!!focus.value;const p=focus.value&&points.get(focus.value.id);if(p)selectionHalo.position.copy(p.position)}recolor()}
function select(n:Node){focus.value=n;emit('focus-pattern',n.pattern);readingIndex.value=0;try{localStorage.setItem('xiyu-atlas-focus',n.id)}catch{}updateHighlight()}
function clearSelection(){focus.value=null;try{localStorage.removeItem('xiyu-atlas-focus')}catch{}updateHighlight()}
function picking(event:PointerEvent){if(!renderer||!camera||!instances)return null;const r=renderer.domElement.getBoundingClientRect();pointer.set((event.clientX-r.left)/r.width*2-1,-(event.clientY-r.top)/r.height*2+1);ray.setFromCamera(pointer,camera);const hit=ray.intersectObjects([instances,...cards.values()],false)[0];return hit?(hit.instanceId!==undefined?data.value!.nodes[hit.instanceId]:hit.object.userData.node as Node):null}
function onDown(event:PointerEvent){if(dragging.value){event.preventDefault();event.stopImmediatePropagation();return}start={x:event.clientX,y:event.clientY};lastInteraction=performance.now();if(!dragMode.value||event.button!==0)return;const n=picking(event);if(!n||!renderer||!camera||!controls)return;event.preventDefault();event.stopImmediatePropagation();select(n);dragNode=n;dragPointer=event.pointerId;dragging.value=true;controls.enabled=false;camera.getWorldDirection(direction);plane.setFromNormalAndCoplanarPoint(direction,points.get(n.id)!.position);if(ray.ray.intersectPlane(plane,planeHit))dragOffset.copy(planeHit).sub(points.get(n.id)!.position);renderer.domElement.setPointerCapture(event.pointerId);syncMotion()}
function onMove(event:PointerEvent){if(dragging.value&&event.pointerId!==dragPointer)return;if(dragging.value&&dragNode&&renderer&&camera){event.preventDefault();event.stopImmediatePropagation();picking(event);if(ray.ray.intersectPlane(plane,planeHit)){const p=points.get(dragNode.id)!;p.position.copy(planeHit).sub(dragOffset);if(p.position.length()>21)p.position.setLength(21);p.updateMatrix();instances!.setMatrixAt(indices.get(dragNode.id)!,p.matrix);instances!.instanceMatrix.needsUpdate=true;instances!.computeBoundingSphere();const card=cards.get(dragNode.id);if(card)card.position.copy(p.position).add(new T.Vector3(0,.5,0));selectionHalo?.position.copy(p.position);changedPositions[dragNode.id]=p.position.toArray();layoutChanged.value=true;updateConnections()}return}const n=picking(event);if((n?.id||'')!==lastHover){lastHover=n?.id||'';hovered.value=n||null;recolor();if(hoverHalo)hoverHalo.visible=!!n}if(renderer)renderer.domElement.style.cursor=dragMode.value?(n?'grab':'crosshair'):(n?'pointer':'grab')}
function endDrag(event:PointerEvent){if(!dragging.value||event.pointerId!==dragPointer)return false;event.preventDefault();event.stopImmediatePropagation();if(renderer?.domElement.hasPointerCapture(dragPointer))renderer.domElement.releasePointerCapture(dragPointer);dragNode=null;dragPointer=-1;dragging.value=false;if(controls)controls.enabled=true;syncMotion();try{localStorage.setItem('xiyu-atlas-layout-v2',JSON.stringify(changedPositions))}catch{}return true}
function onUp(event:PointerEvent){lastInteraction=performance.now();if(endDrag(event))return;if(Math.hypot(event.clientX-start.x,event.clientY-start.y)<5){const n=picking(event);if(n)select(n)}}
function onLeave(){if(!dragging.value){hovered.value=null;lastHover='';if(hoverHalo)hoverHalo.visible=false;recolor()}}
function glow(){const canvas=document.createElement('canvas');canvas.width=canvas.height=128;const ctx=canvas.getContext('2d')!,g=ctx.createRadialGradient(64,64,4,64,64,64);g.addColorStop(0,'#fff5c8');g.addColorStop(.15,'#ffe2a1');g.addColorStop(.4,'#e6bc7766');g.addColorStop(1,'#e6bc7700');ctx.fillStyle=g;ctx.fillRect(0,0,128,128);return new T.CanvasTexture(canvas)}
function atmosphere(){if(!scene)return;scene.add(new T.LineSegments(new T.WireframeGeometry(new T.SphereGeometry(9.75,32,16)),new T.LineBasicMaterial({color:0x89b9ad,transparent:true,opacity:.075,depthWrite:false})));for(const [radius,x,z] of [[12.6,.16,.4],[14.2,.7,-.35],[15.3,-.4,.15]]){const positions=[];for(let i=0;i<=160;i++){const a=i/160*Math.PI*2;positions.push(Math.cos(a)*radius!,0,Math.sin(a)*radius!)}const geometry=new T.BufferGeometry();geometry.setAttribute('position',new T.Float32BufferAttribute(positions,3));const ring=new T.Line(geometry,new T.LineBasicMaterial({color:0xc9b582,transparent:true,opacity:.23,depthWrite:false}));ring.rotation.set(x!,0,z!);scene.add(ring)}const stars:number[]=[];let state=7321;const random=()=>{state=(state*1664525+1013904223)>>>0;return state/4294967296};for(let i=0;i<480;i++){const theta=random()*Math.PI*2,z=random()*2-1,r=32+random()*34,s=Math.sqrt(1-z*z);stars.push(r*s*Math.cos(theta),r*z,r*s*Math.sin(theta))}const geometry=new T.BufferGeometry();geometry.setAttribute('position',new T.Float32BufferAttribute(stars,3));scene.add(new T.Points(geometry,new T.PointsMaterial({color:0xc7d9d3,size:.045,transparent:true,opacity:.55,sizeAttenuation:true,depthWrite:false})));const texture=glow();selectionHalo=new T.Sprite(new T.SpriteMaterial({map:texture,color:0xffe0a0,transparent:true,opacity:.72,depthWrite:false,blending:T.AdditiveBlending}));selectionHalo.scale.set(1.6,1.6,1);selectionHalo.visible=false;scene.add(selectionHalo);hoverHalo=new T.Sprite(new T.SpriteMaterial({map:texture,color:0xe5ffef,transparent:true,opacity:.6,depthWrite:false,blending:T.AdditiveBlending}));hoverHalo.scale.set(1.1,1.1,1);hoverHalo.visible=false;scene.add(hoverHalo)}
function restoreLayout(){try{const raw=JSON.parse(localStorage.getItem('xiyu-atlas-layout-v2')||'{}');for(const [id,xyz] of Object.entries(raw)){if(!points.has(id)||!Array.isArray(xyz)||xyz.length!==3||!xyz.every(n=>typeof n==='number'&&Number.isFinite(n)))continue;const v=new T.Vector3(...xyz as [number,number,number]);if(v.length()<=21){points.get(id)!.position.copy(v);changedPositions[id]=xyz;layoutChanged.value=true}}}catch{}}
function resetLayout(){for(const p of points.values()){p.position.copy(p.userData.origin);p.updateMatrix();instances?.setMatrixAt(indices.get(p.userData.node.id)!,p.matrix);cards.get(p.userData.node.id)?.position.copy(p.position).add(new T.Vector3(0,.5,0))}if(instances){instances.instanceMatrix.needsUpdate=true;instances.computeBoundingSphere()}for(const key of Object.keys(changedPositions))delete changedPositions[key];layoutChanged.value=false;try{localStorage.removeItem('xiyu-atlas-layout-v2')}catch{}updateConnections();updateHighlight();resetView()}
onMounted(async()=>{try{const response=await fetch('/api/creation/atlas',{signal:abortController.signal});if(!response.ok)throw Error('atlas');data.value=await response.json();if(!alive)return;loading.value=false;const remembered=localStorage.getItem('xiyu-atlas-focus');if(remembered)focus.value=data.value!.nodes.find(n=>n.id===remembered)||null;if(focus.value)emit('focus-pattern',focus.value.pattern);
try{scene=new T.Scene();camera=new T.PerspectiveCamera(48,1,.1,180);camera.position.set(0,7,33);renderer=new T.WebGLRenderer({antialias:true,alpha:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));host.value!.appendChild(renderer.domElement);renderer.domElement.addEventListener('pointerdown',onDown,true);renderer.domElement.addEventListener('pointermove',onMove,true);renderer.domElement.addEventListener('pointerup',onUp,true);renderer.domElement.addEventListener('pointercancel',endDrag,true);renderer.domElement.addEventListener('pointerleave',onLeave);controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.dampingFactor=.06;controls.minDistance=5;controls.maxDistance=76;controls.autoRotateSpeed=.5;controls.addEventListener('start',()=>{lastInteraction=performance.now()});
const nodes=data.value!.nodes;instances=new T.InstancedMesh(new T.SphereGeometry(1,10,8),new T.MeshBasicMaterial(),nodes.length);instances.instanceMatrix.setUsage(T.DynamicDrawUsage);scene.add(instances);let pi=0,gi=0;const pc=nodes.filter(n=>n.kind==='pattern').length,gc=nodes.length-pc;for(let i=0;i<nodes.length;i++){const n=nodes[i]!,isPattern=n.kind==='pattern',j=isPattern?pi++:gi++,count=isPattern?pc:gc,y=1-2*(j+.5)/count,angle=j*2.3999632297+(isPattern?.4:0),radius=isPattern?11.7:10.3+((j%7)/7)*.5,s=Math.sqrt(1-y*y),pos=new T.Vector3(Math.cos(angle)*s*radius,y*radius,Math.sin(angle)*s*radius);const p=new T.Object3D();p.position.copy(pos);p.userData={node:n,origin:pos.clone()};p.scale.setScalar(isPattern?.21:n.kind==='知识文章'?.17:n.kind==='图元'?.105:.085);p.updateMatrix();points.set(n.id,p);indices.set(n.id,i);baseColors.set(n.id,new T.Color(colors[n.kind]||0xb9cdbd))}
restoreLayout();for(const n of nodes){const p=points.get(n.id)!;p.updateMatrix();instances.setMatrixAt(indices.get(n.id)!,p.matrix);instances.setColorAt(indices.get(n.id)!,baseColors.get(n.id)!);if(n.kind==='pattern'&&n.image){const texture=new T.TextureLoader().load(n.thumbnail||n.image);texture.colorSpace=T.SRGBColorSpace;const card=new T.Mesh(new T.PlaneGeometry(.74,.74),new T.MeshBasicMaterial({map:texture,transparent:true,opacity:.88,side:T.DoubleSide,depthWrite:false}));card.position.copy(p.position).add(new T.Vector3(0,.5,0));card.userData={node:n};cards.set(n.id,card);scene.add(card)}}instances.computeBoundingSphere();
for(const layer of [{edges:data.value!.edges.filter(e=>e.kind==='contains'),color:0x7aa798,opacity:.12},{edges:data.value!.edges.filter(e=>e.kind==='mapping'&&e.status==='已确认'),color:0xd6bc85,opacity:.3},{edges:data.value!.edges.filter(e=>e.kind==='mapping'&&e.status!=='已确认'),color:0xb89aa3,opacity:.16},{edges:data.value!.edges.filter(e=>e.kind==='reading'),color:0x9fc8f2,opacity:.32},{edges:data.value!.edges.filter(e=>e.kind==='derivation'),color:0xc4a2dc,opacity:.33}]){const geometry=new T.BufferGeometry();geometry.setAttribute('position',new T.Float32BufferAttribute(coordinates(layer.edges),3));const lines=new T.LineSegments(geometry,new T.LineBasicMaterial({color:layer.color,transparent:true,opacity:layer.opacity,depthWrite:false}));scene.add(lines);edgeLayers.push({edges:layer.edges,lines})}
atmosphere();syncMotion();updateHighlight();observer=new ResizeObserver(()=>{if(!renderer||!camera||!host.value)return;const w=host.value.clientWidth,h=host.value.clientHeight;renderer.setSize(w,h);camera.aspect=w/Math.max(1,h);camera.updateProjectionMatrix()});observer.observe(host.value!);
function tick(time:number){if(!alive)return;frame=requestAnimationFrame(tick);const delta=previousTime?Math.min((time-previousTime)/1000,.05):.016;previousTime=time;if(controls){controls.autoRotate=rotating.value&&!dragMode.value&&!dragging.value&&time-lastInteraction>1300;controls.update(delta)}for(const card of cards.values())card.quaternion.copy(camera!.quaternion);if(hovered.value&&hoverHalo){hoverHalo.position.copy(points.get(hovered.value.id)!.position);if(hoverLabel.value&&host.value){scratch.copy(hoverHalo.position).project(camera!);hoverLabel.value.style.left=`${Math.max(12,Math.min(host.value.clientWidth-200,(scratch.x*.5+.5)*host.value.clientWidth+14))}px`;hoverLabel.value.style.top=`${Math.max(78,Math.min(host.value.clientHeight-90,(-scratch.y*.5+.5)*host.value.clientHeight-24))}px`}}if(selectionHalo)selectionHalo.material.opacity=.62+Math.sin(time*.002)*.1;renderer!.render(scene!,camera!)}frame=requestAnimationFrame(tick);
}catch{failed.value=true}}catch{loading.value=false;failed.value=true}});
onBeforeUnmount(()=>{alive=false;abortController.abort();cancelAnimationFrame(frame);observer?.disconnect();controls?.dispose();const geometries=new Set<T.BufferGeometry>(),materials=new Set<T.Material>(),textures=new Set<T.Texture>();scene?.traverse((o:any)=>{if(o.geometry)geometries.add(o.geometry);for(const m of Array.isArray(o.material)?o.material:[o.material])if(m){materials.add(m);if(m.map)textures.add(m.map)}});for(const g of geometries)g.dispose();for(const m of materials)m.dispose();for(const t of textures)t.dispose();renderer?.dispose()});
</script>
<template>
<section class="atlas-world planet-atlas">
 <div class="world-heading planet-heading"><div><p>纹脉织境 / 让文化的联系被看见</p><h2>万纹如星，<em>循意而行。</em></h2><span>{{data?.nodes.length||'—'}} 个纹样与知识节点 · {{data?.edges.length||'—'}} 条资料联系</span></div><div class="planet-key"><span><i class="key-pattern"></i>纹样</span><span><i class="key-gene"></i>基因</span><span><i class="key-meaning"></i>意象</span><span><i class="key-reading"></i>知识</span></div></div>
 <div class="world-layout planet-layout"><div class="world-canvas planet-canvas" ref="host" :class="{'is-dragging':dragging,'node-drag-mode':dragMode}" aria-label="可旋转的三维纹样星球">
  <div class="planet-toolbar" aria-label="星球视角与交互"><button :aria-pressed="rotating" @click="toggleRotation">{{rotating?'Ⅱ 暂停自转':'▷ 开启自转'}}</button><button :aria-pressed="dragMode" @click="toggleDrag">{{dragMode?'✓ 移动节点':'移动节点'}}</button><button @click="resetView">复位视角</button><button aria-label="放大图谱" @click="zoom(.8)">＋</button><button aria-label="缩小图谱" @click="zoom(1.25)">−</button></div>
  <div v-if="loading" class="planet-state" role="status">正在展开纹样星球…</div><div v-else-if="failed" class="planet-state">三维场景暂不可用，可通过节点列表继续探索。</div><div v-if="hovered" ref="hoverLabel" class="planet-hover"><small>{{hovered.kind==='pattern'?'纹样档案':hovered.kind}} · {{hovered.pattern}}</small><b>{{hovered.label}}</b></div>
  <div class="planet-canvas-note"><span class="planet-live-dot"></span>{{dragging?'移动后，联系随节点一起更新':dragMode?'按住节点，移动它在星球中的阅读位置':'拖动环视 · 滚轮缩放 · 点击星点，读见来处'}}<button v-if="layoutChanged" @click="resetLayout">还原布局</button></div><div class="planet-compass" aria-hidden="true"><span>形</span><i></i><span>意</span></div>
 </div><aside class="planet-inspector">
  <div class="planet-search"><input v-model="query" placeholder="搜索纹样、意象、图元" aria-label="搜索全库图谱"><button v-if="query" @click="query=''" aria-label="清除图谱搜索">✕</button></div>
  <template v-if="focus&&!query"><div class="planet-focus-heading"><button @click="clearSelection">← 浏览全部节点</button><span>{{focus.kind==='pattern'?'纹样档案':focus.kind}}</span></div><span v-if="contemporary" class="planet-contemporary">当代创作 · 保留派生来源</span><h3>{{focus.label}}</h3><small class="planet-source-code">{{focus.pattern}}<template v-if="focus.code"> · {{focus.code}}</template></small>
   <div class="planet-selected-art" :class="{'art-contemporary':selectedPattern?.origin==='contemporary'}" v-if="focus.image"><img :src="focus.thumbnail||focus.image" :alt="focus.label"><div><span>此刻选中</span><p>{{selectedPattern?.label||focus.label}}</p><button @click="locate">定位此节点 ⊙</button></div></div>
   <section v-if="focus.kind==='知识文章'" class="planet-knowledge-focus"><p>{{focus.summary}}</p><button @click="emit('read',focus.article_id)">展开这篇知识阅读 ↗</button><div v-if="focus.source_refs?.length" class="planet-knowledge-refs"><a v-for="source in focus.source_refs" :href="referenceUrl(source.url)" target="_blank" rel="noopener noreferrer"><span>{{source.title}} ↗</span><small>{{source.organization}}</small></a></div><small>阅读参照不等同于关联样本的原始出处。</small></section>
   <section v-if="contextRelations.length" class="planet-context-relations"><h4>循线查阅 · {{contextRelations.length}} 条联系</h4><article v-for="e in contextRelations.slice(0,3)" :key="e.kind+e.source+e.target"><span :class="{'relation-derivation':e.kind==='derivation'}">{{e.kind==='derivation'?'创作派生':'阅读参考'}}</span><button @click="followRelation(e)">{{relatedNode(e)?.label||'关联条目'}} ↗</button><p>{{e.evidence}}</p></article><details v-if="contextRelations.length>3"><summary>展开其余 {{contextRelations.length-3}} 条来源联系</summary><article v-for="e in contextRelations.slice(3)" :key="e.kind+e.source+e.target"><span :class="{'relation-derivation':e.kind==='derivation'}">{{e.kind==='derivation'?'创作派生':'阅读参考'}}</span><button @click="followRelation(e)">{{relatedNode(e)?.label||'关联条目'}} ↗</button><p>{{e.evidence}}</p></article></details></section>
